import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.DfDAiEgj.js";const _=JSON.parse('{"title":"原型检验1","description":"","frontmatter":{},"headers":[],"relativePath":"project/inspect.md","filePath":"project/inspect.md","lastUpdated":null}'),p={name:"project/inspect.md"};function n(c,e,i,l,s,d){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="原型检验1" tabindex="-1">原型检验<a href="http://www.woshipm.com/pmd/21446.html" target="_blank" rel="noreferrer">1</a> <a class="header-anchor" href="#原型检验1" aria-label="Permalink to &quot;原型检验[1]&quot;">​</a></h1><p>容易犯一个常见的错误，他们对产品设计规范太有信心，结果一旦得到beta的测试他们就必须调整产品。但是肯定beta测试版并不是进行重大改变的时候，所以才会有许多首次发布的产品离目标太远。</p><h2 id="可行性测试" tabindex="-1">可行性测试 <a class="header-anchor" href="#可行性测试" aria-label="Permalink to &quot;可行性测试&quot;">​</a></h2><p>一个直接的问题就是产品是否可以开发，你的工程师和设计师应当介入技术的可行性调查和探索可用办法。有些办法是行不通的，但是有其他的办法可行是非常有希望的。 工程师会发现在产品的某个阶段不可能逾越，现在知道比以后知道要好。</p><h2 id="可用性测试" tabindex="-1">可用性测试 <a class="header-anchor" href="#可用性测试" aria-label="Permalink to &quot;可用性测试&quot;">​</a></h2><p>产品设计师将要和你紧密工作共同提出产品功能，让它能适应不同的用户。可用性测试常常会找出遗漏的产品要求，同时确认产品最初的要求是否是必须的。在你拿出一个成功的用户体验之前需要多做一些测试工作。可用性的目的是在真正的用户身上测试，从产品目标用户得到质量反馈的测试是非常艺术和科学的。当然产品经理和产品设计将模仿使用，但是实际是没有人能取代真实的目标用户。</p><p>观看其他人试着使用您正在（或已经）创建/设计/建造的产品，目的是 <a href="https://36kr.com/p/1721288867841" target="_blank" rel="noreferrer">2</a></p><ol><li>让它使用起来更容易；</li><li>证明它容易使用。</li></ol><h2 id="概念测试-product-concept-testing" tabindex="-1">概念测试（Product Concept Testing） <a class="header-anchor" href="#概念测试-product-concept-testing" aria-label="Permalink to &quot;概念测试（Product Concept Testing）&quot;">​</a></h2><p>光是可用和可行是不足的。真正的问题是你的用户想要购买吗—你的用户有多喜欢-你做的有什么价值。这测试可能与可用性测试联系在一起。</p><p>对于一部份小产品，您的想法写在纸就足够了，但是对于多数产品，为了预计产品是否达到目标，复杂用户互作用或新技术的使用、某种形式原型都是非常重要的。</p><p>原型也许是一个物理设备，或者它也许是软件产品的一个预览版本。关键是它需要足够现实，您能用原型在实际目标顾客身上测试，并且他们可以给您质量反馈。</p><p>以前做原型主要有两个障碍。第一是缺乏良好的原型工具，需要花费很多的时间制作原型；另一个是管理方不知道原型和真实产品的区别，在不可预计的情况下，按照最终产品来要求原型。</p>',13)])])}const m=t(p,[["render",n]]);export{_ as __pageData,m as default};
